import{_ as a,o as n,c as e,a2 as s}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"后端学习计划","description":"这一页只讲「后端要学什么、按什么顺序学」。 Agent 相关的学习资源与面试题清单在别处: - 学习资源与转行思路 → Agent 讨论摘录 - Agent 岗位面试会问什么 → Agent 讨论摘录(含真实面试题清单) - Pytho","frontmatter":{},"headers":[],"relativePath":"agent/2-Backend.md","filePath":"agent/2-Backend.md","lastUpdated":1793545253000}'),o={name:"agent/2-Backend.md"};function r(l,t,i,d,g,p){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="后端学习计划" tabindex="-1">后端学习计划 <a class="header-anchor" href="#后端学习计划" aria-label="Permalink to &quot;后端学习计划&quot;">​</a></h1><blockquote><p><strong>这一页只讲「后端要学什么、按什么顺序学」</strong>。 Agent 相关的学习资源与面试题清单在别处:</p><ul><li>学习资源与转行思路 → <a href="./4-agent-讨论">Agent 讨论摘录</a></li><li>Agent 岗位面试会问什么 → <a href="./4-agent-讨论">Agent 讨论摘录</a>(含真实面试题清单)</li><li>Python 基础 → <a href="./../agent/python/">Python 基础</a></li></ul></blockquote><h2 id="一、为什么前端要补后端" tabindex="-1">一、为什么前端要补后端 <a class="header-anchor" href="#一、为什么前端要补后端" aria-label="Permalink to &quot;一、为什么前端要补后端&quot;">​</a></h2><p>Agent 应用的<strong>一半工作量在后端</strong>:工具服务化、会话状态持久化、流式响应、成本控制。 只会调 API 不够,得能把 Agent 真正<strong>部署成一个服务</strong>。</p><h2 id="二、学习顺序-按依赖排-不要跳" tabindex="-1">二、学习顺序(按依赖排,不要跳) <a class="header-anchor" href="#二、学习顺序-按依赖排-不要跳" aria-label="Permalink to &quot;二、学习顺序(按依赖排,不要跳)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 编程语言基础   → Python(见 agent/python/)或 TypeScript/Node</span></span>
<span class="line"><span>② 数据库         → MySQL 基础、索引、事务、锁</span></span>
<span class="line"><span>③ 打通最小闭环   → 先写一个「登录页 + 一个接口」,把前后端串起来</span></span>
<span class="line"><span>④ Web 框架       → Express / FastAPI / NestJS</span></span>
<span class="line"><span>⑤ 缓存与中间件  → Redis、限流、日志、错误处理</span></span>
<span class="line"><span>⑥ 部署          → Docker → Nginx → CI/CD</span></span>
<span class="line"><span>⑦ 编排          → K8s / Serverless(进阶,按需)</span></span></code></pre></div><p><strong>关键</strong>:每学一块就<strong>接到 Agent 上</strong>。比如学完 FastAPI 就把模型调用包成接口,学完 Redis 就把会话状态存进去。不要学完再串。</p><h2 id="三、每一块的验收标准" tabindex="-1">三、每一块的验收标准 <a class="header-anchor" href="#三、每一块的验收标准" aria-label="Permalink to &quot;三、每一块的验收标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>验收标准</th></tr></thead><tbody><tr><td>② 数据库</td><td>能说清「联合索引为什么用最左前缀」「事务隔离级别分别解决什么」</td></tr><tr><td>③ 最小闭环</td><td>能独立把登录 + 列表 + 分页跑通</td></tr><tr><td>④ Web 框架</td><td>能写一个带中间件(鉴权 + 日志 + 统一错误)的接口</td></tr><tr><td>⑤ 缓存</td><td>能说清「什么数据能缓存、失效策略怎么定」</td></tr><tr><td>⑥ 部署</td><td>能把服务打成镜像推到服务器并用 Nginx 反代</td></tr><tr><td>⑦ 编排</td><td>能解释「为什么需要编排,不用 K8s 的代价是什么」</td></tr></tbody></table><h2 id="四、agent-后端特有的三件事" tabindex="-1">四、Agent 后端特有的三件事 <a class="header-anchor" href="#四、agent-后端特有的三件事" aria-label="Permalink to &quot;四、Agent 后端特有的三件事&quot;">​</a></h2><p>这三件事是普通后端课程不会讲的,也是面试里能体现差异化的地方:</p><ol><li><strong>工具服务化</strong>——把业务能力(查订单、查知识库、发消息)做成<strong>模型可调用的工具</strong>,而不是让模型自己编</li><li><strong>会话与状态持久化</strong>——Agent 的 state 要能存(数据库)、能恢复(checkpoint)、能按用户隔离</li><li><strong>流式响应</strong>——模型是慢的,必须流式吐字,否则体验崩;这涉及 SSE、WebSocket 与前端增量渲染</li></ol><h2 id="五、最终验收" tabindex="-1">五、最终验收 <a class="header-anchor" href="#五、最终验收" aria-label="Permalink to &quot;五、最终验收&quot;">​</a></h2><blockquote><p>能独立部署一个「上传文档 → 建索引 → 提问 → 带引用回答」的服务,并在公网访问。</p></blockquote><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>后端学习的目的是<strong>能独立把 Agent 跑起来</strong>:API、数据、鉴权、部署这四块必须自己动手过一遍。</li><li>顺序:<strong>Python/Node 基础 → 数据库 → 打通最小闭环 → Web 框架 → 缓存中间件 → Docker 部署 → 编排(按需)</strong>。</li><li>Agent 后端特有的三件事:<strong>工具服务化</strong>、<strong>会话与状态持久化</strong>、<strong>流式响应</strong>。</li><li>学习方式:<strong>每学一块就接到 Agent 上</strong>,避免学完再串。</li><li>面试加分:讲「<strong>我的技术栈从纯前端扩展到能用 Node/Python 独立交付一个 AI 服务</strong>」,这是很好的转型叙事。</li><li>Agent 侧的学习资源与真实面试题 → <a href="./4-agent-讨论">Agent 讨论摘录</a>。</li></ul>`,16)])])}const b=a(o,[["render",r]]);export{c as __pageData,b as default};
